    ctx->level--;
    PCC_DEBUG(ctx->auxil, PCC_DBG_MATCH, "sp1", ctx->level, chunk->pos, ctx->buffer.p + chunk->pos, ctx->cur - chunk->pos);
    pcc_marker_variable_set_entry__copy(ctx->auxil, &(chunk->mvars), &(ctx->mvars.curr));
